"""Run complete selected PPPoE parser/discovery functions with modeled IO.
Inputs are taken from the current patched PPP build, never from archived research outputs.
Requires a prepared PPP build, gcc and ASan/UBSan. This does not run a network session.
"""
from pathlib import Path
import re,subprocess,json,os,hashlib
ROOT=Path(__file__).resolve().parents[2]
P=Path(os.environ.get('B27_PPP_DIR',str(ROOT/'build_dir/target-aarch64_cortex-a53_musl/linux-airoha_an7581/ppp-default/ppp-2.5.4')))
OUT=Path(os.environ.get('B27_TEST_DIR','/tmp/xr1710g-reviewed-fixes-tests'))/'ppp-discovery';OUT.mkdir(parents=True,exist_ok=True)
D=P/'pppd/plugins/pppoe'
NL=chr(10)
def extract(path,name):
 s=path.read_text()
 ws='['+chr(9)+chr(13)+chr(10)+' ]'
 pattern='^(?:static'+ws+'+)?(?:void|int)'+ws+'*'+re.escape(name)+'[(][^;]*?[)]'+ws+'*[{]'
 m=re.search(pattern,s,re.M);assert m,(path,name)
 end=s.find(NL+'}',m.end());assert end>0;return s[m.start():end+2]
PREFIX='\n#define _GNU_SOURCE 1\n#include <assert.h>\n#include <stdlib.h>\n#include <stdio.h>\n#include <stdarg.h>\n#include <string.h>\n#include <errno.h>\n#include <signal.h>\n#include <sys/time.h>\n#include <unistd.h>\n#define HAVE_NETPACKET_PACKET_H 1\n#define HAVE_SYS_SOCKET_H 1\n#define HAVE_NET_IF_H 1\n#define HAVE_LINUX_IF_ETHER_H 1\n#define HAVE_STRUCT_SOCKADDR_LL 1\n#define SIZEOF_UNSIGNED_SHORT 2\n#define SIZEOF_UNSIGNED_INT 4\n#include "pppd/plugins/pppoe/pppoe.h"\nint pppoe_verbose;\nUINT16_t Eth_PPPOE_Discovery=ETH_PPPOE_DISCOVERY;\nstatic PPPoEPacket incoming[4],outgoing;\nstatic int ninput,atinput,noutput,outsize;\nvoid info(const char *fmt,...) {}\nvoid error(const char *fmt,...) {}\nvoid warn(const char *fmt,...) {}\nvoid fatal(const char *fmt,...) {abort();}\nint get_time(struct timeval *tv) {tv->tv_sec=100;tv->tv_usec=0;return 0;}\nint signaled(int signo) {return 0;}\nstatic int modeled_select(int n,fd_set*r,fd_set*w,fd_set*e,struct timeval*t){return atinput<ninput?1:0;}\nstatic ssize_t modeled_recv(int fd,void*p,size_t n,int flags){assert(atinput<ninput);int len=HDR_SIZE+ntohs(incoming[atinput].length);assert((size_t)len<=n);memcpy(p,&incoming[atinput++],len);return len;}\nstatic ssize_t modeled_send(int fd,const void*p,size_t n,int flags){assert(n<=sizeof(outgoing));memcpy(&outgoing,p,n);outsize=n;noutput++;return n;}\nstatic size_t test_strlcpy(char*d,const char*s,size_t n){size_t len=strlen(s);if(n){size_t k=len<n-1?len:n-1;memcpy(d,s,k);d[k]=0;}return len;}\n#define select modeled_select\n#define recv modeled_recv\n#define send modeled_send\n#define strlcpy test_strlcpy\n#define debug_on() 0\n#define pppoe_log_packet(a,b) ((void)0)\n'
HELPERS='static void tag(PPPoEPacket*p,unsigned short kind,const void*data,unsigned n){unsigned off=ntohs(p->length);unsigned char*d=p->payload+off;d[0]=kind>>8;d[1]=kind;d[2]=n>>8;d[3]=n;memcpy(d+4,data,n);p->length=htons(off+4+n);}\nstatic void offer(PPPoEPacket*p,PPPoEConnection*c,int mac,const char*ac,const char*svc,int cookie,int relay,int maxpayload,int bad){memset(p,0,sizeof(*p));p->vertype=PPPOE_VER_TYPE(1,1);p->code=CODE_PADO;p->ethHdr.h_proto=htons(ETH_PPPOE_DISCOVERY);memcpy(p->ethHdr.h_dest,c->myEth,6);p->ethHdr.h_source[0]=2;p->ethHdr.h_source[5]=mac;if(ac)tag(p,TAG_AC_NAME,ac,strlen(ac));if(svc)tag(p,TAG_SERVICE_NAME,svc,strlen(svc));if(cookie)tag(p,TAG_AC_COOKIE,"OLD-COOKIE",10);if(relay)tag(p,TAG_RELAY_SESSION_ID,"OLD-RELAY",9);if(maxpayload){unsigned short v=htons(maxpayload);tag(p,TAG_PPP_MAX_PAYLOAD,&v,2);}if(bad)tag(p,TAG_GENERIC_ERROR,"NO",2);}\n'
GRID='int main(void){\n int cases=0,bad=0,category[7]={0};\n for(int filters=0;filters<4;filters++)for(int ac=0;ac<3;ac++)for(int svc=0;svc<3;svc++)for(int cookie=0;cookie<2;cookie++)for(int relay=0;relay<2;relay++)for(int maxp=0;maxp<3;maxp++)for(int err=0;err<2;err++)for(int whole=0;whole<2;whole++)for(int host=0;host<3;host++)for(int malformed=0;malformed<2;malformed++) {\n  const char*acname=ac==0?"wanted-ac":ac==1?"other-ac":NULL;\n  const char*service=svc==0?"wanted-service":svc==1?"other-service":NULL;\n  int first_valid=acname&&service&&(!(filters&1)||ac==0)&&(!(filters&2)||svc==0)&&!err&&host!=2&&!malformed;\n  PPPoEConnection c={0};c.discoverySocket=7;c.mtu=c.mru=1500;c.discoveryState=STATE_SENT_PADI;c.myEth[0]=2;c.myEth[5]=9;\n  c.acName=filters&1?"wanted-ac":NULL;c.serviceName=filters&2?"wanted-service":NULL;\n  if(host){c.hostUniq.type=htons(TAG_HOST_UNIQ);c.hostUniq.length=htons(4);memcpy(c.hostUniq.payload,"ID42",4);}\n  atinput=ninput=noutput=outsize=0;\n  offer(&incoming[ninput++],&c,1,acname,service,cookie,relay,maxp==1?1492:maxp==2?1500:0,err);\n  offer(&incoming[ninput++],&c,2,"wanted-ac","wanted-service",0,0,1500,0);\n  if(host){tag(&incoming[0],TAG_HOST_UNIQ,host==2?"BAD!":"ID42",4);tag(&incoming[1],TAG_HOST_UNIQ,"ID42",4);}\n  if(malformed){unsigned n=ntohs(incoming[0].length);memcpy(incoming[0].payload+n,"\\xff\\xfe\\xff\\xff",4);incoming[0].length=htons(n+4);}\n  waitForPADO(&c,2,whole);\n  int failure[7]={c.discoveryState!=STATE_RECEIVED_PADO,c.peerEth[5]!=(first_valid?1:2),!!c.cookie.type!=(first_valid?cookie:0),!!c.relayId.type!=(first_valid?relay:0),c.mtu!=(first_valid&&maxp==1?1492:1500)||c.mru!=(first_valid&&maxp==1?1492:1500),!c.actualACname||strcmp(c.actualACname,first_valid?acname:"wanted-ac"),0};\n  if(c.discoveryState==STATE_RECEIVED_PADO){sendPADR(&c);failure[6]=memcmp(outgoing.ethHdr.h_dest,c.peerEth,6)!=0||outsize!=HDR_SIZE+ntohs(outgoing.length);}\n  int hit=0;for(int i=0;i<7;i++){category[i]+=!!failure[i];hit|=failure[i];}bad+=!!hit;cases++;\n  if(hit&&bad<=12)fprintf(stderr,"case %d filters=%d ac=%d svc=%d cookie=%d relay=%d maxp=%d err=%d whole=%d host=%d malformed=%d selected=%d expected_first=%d mtu=%d mask=%d%d%d%d%d%d%d\\n",cases,filters,ac,svc,cookie,relay,maxp,err,whole,host,malformed,c.peerEth[5],first_valid,c.mtu,failure[0],failure[1],failure[2],failure[3],failure[4],failure[5],failure[6]);\n  free(c.actualACname);\n }\n printf("{\\"cases\\":%d,\\"unsafe_cases\\":%d,\\"categories\\":[%d,%d,%d,%d,%d,%d,%d]}\\n",cases,bad,category[0],category[1],category[2],category[3],category[4],category[5],category[6]);\n return 0;\n}\n'
BOUNDARY='int main(void) {\n unsigned cases=0;\n for(unsigned n=0;n<=MAX_PPPOE_PAYLOAD-TAG_HDR_SIZE;n++)for(unsigned embedded=0;embedded<2;embedded++){\n  PPPoEPacket *packet=malloc(sizeof(*packet));assert(packet);memset(packet,0xa5,sizeof(*packet));packet->vertype=PPPOE_VER_TYPE(1,1);packet->length=0;\n  unsigned char data[MAX_PPPOE_PAYLOAD];memset(data,\'A\',sizeof(data));if(n&&embedded)data[n/2]=0;tag(packet,TAG_AC_NAME,data,n);\n  PPPoEConnection conn={0};struct PacketCriteria pc={.conn=&conn};\n  assert(parsePacket(packet,parsePADOTags,&pc)==0);assert(pc.seenACName&&conn.actualACname);\n  assert(!memcmp(conn.actualACname,data,n)&&conn.actualACname[n]==0);free(conn.actualACname);free(packet);cases++;\n }\n printf("PASS boundary cases %u\\n",cases);return 0;\n}\n'
FUNCTIONS=[('common.c','parsePacket'),('discovery.c','time_left'),('discovery.c','parseForHostUniq'),('discovery.c','packetIsForMe'),('discovery.c','parsePADOTags'),('if.c','sendPacket'),('if.c','receivePacket'),('discovery.c','sendPADI'),('discovery.c','waitForPADO'),('discovery.c','sendPADR')]
actual=(NL*2).join(extract(D/file,name) for file,name in FUNCTIONS)
results=[]
for label,main in [('offer-grid',GRID),('ac-name-boundaries',BOUNDARY)]:
 src=OUT/(label+'.c');src.write_text(PREFIX+actual+HELPERS+main)
 cmd=['gcc','-O1','-g','-fsanitize=address,undefined','-fno-omit-frame-pointer','-I'+str(P),'-I'+str(P/'pppd'),str(src),'-o',str(OUT/label)]
 r=subprocess.run(cmd,capture_output=True,text=True);(OUT/(label+'-build.log')).write_text(r.stdout+r.stderr);assert r.returncode==0,r.stderr
 r=subprocess.run([str(OUT/label)],capture_output=True,text=True,env=dict(os.environ,ASAN_OPTIONS='detect_leaks=1'));(OUT/(label+'-run.log')).write_text(r.stdout+r.stderr);assert r.returncode==0,r.stdout+r.stderr
 if label=='offer-grid':assert json.loads(r.stdout)['unsafe_cases']==0
 else:assert r.stdout.strip()=='PASS boundary cases 2998'
 results.append(dict(test=label,output=r.stdout,generated_source_sha256=hashlib.sha256(src.read_bytes()).hexdigest()))
report=dict(status='PASS',results=results,input_sources=[dict(path=str(D/name),sha256=hashlib.sha256((D/name).read_bytes()).hexdigest()) for name in ['common.c','discovery.c','if.c']],limits=['Complete selected functions with real PPP headers; send/recv/select/clock/logging are modeled.','The strlcpy fallback deliberately scans to NUL, so reverting R28 remains detectable under ASan.','Synthetic offer and length inputs; no ISP or user-symptom proof.'])
(OUT/'verification.json').write_text(json.dumps(report,indent=2));print(json.dumps(report))
